(function(E){ const x = E["int-m3"] = E["int-m3"] || {units:{}}; x.units["int-cp-3"] = {"exit":{"id":"c-int-cp-3-x","course":"interview","unit":"int-cp-3","type":"exit","items":[{"from":"int-7","kind":"blank","prompt":"How often ___ your team meet with clients?","options":["does","is","do"],"correct":0},{"from":"int-7","kind":"mcq","prompt":"Which thank-you line is strongest?","options":["I enjoyed hearing about your plan to open in Konya, and I am still very interested.","Thank you for the meeting. I hope you choose me, because I really need this job.","Thank you for your time. Please also tell me your salary range and holiday days."],"correct":0},{"from":"int-8","kind":"blank","prompt":"If a client ___ angry, I would listen first.","options":["got","will get","would get"],"correct":0},{"from":"int-8","kind":"mcq","prompt":"\"Why did you leave your last job?\" Which answer is best?","options":["My manager was awful, and nobody could work with him.","I wanted more responsibility, and this role offers it.","I don't want to talk about that, if you don't mind."],"correct":1},{"from":"int-9","kind":"blank","prompt":"I was ___ if the start date could move to May.","options":["wondering","wonder","wondered"],"correct":0},{"from":"int-9","kind":"mcq","prompt":"You have three requests about an offer. What is the best way to ask?","options":["One at a time, over several weeks, so they don't feel pressure","All in one message, the most important first, each with a reason","Only the biggest one, as a final demand, with a date to answer"],"correct":1},{"from":"int-5","kind":"mcq","prompt":"Which line gives the Result of a story?","options":["I phoned every customer myself that same evening.","In the end, we kept all twelve customers.","Last spring the system stopped during a big sale."],"correct":1},{"from":"int-2","kind":"blank","prompt":"I would prefer ___ on the first of June, if that is possible.","options":["to start","start","starting to"],"correct":0}]},"writing":{"id":"c-int-cp-3-w","title":{"en":"Your two emails after the interview","tr":"Mülakattan sonra iki e-postan","fa":"دو ایمیل تو بعد از مصاحبه"},"course":"interview","unit":"int-cp-3","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"int-final-6","prompt":{"en":"Write the two emails you will need after an interview (80-110 words in total). Email 1, within 24 hours: thank them, mention one real thing from the conversation, say you are still interested. Email 2, after the date they gave you has passed: say you are still interested, and ask politely about the next steps.","tr":"Mülakattan sonra gerekecek iki e-postayı yaz (toplam 80-110 kelime). 1. e-posta, 24 saat içinde: teşekkür et, görüşmeden gerçek bir şeyi an, hâlâ ilgilendiğini söyle. 2. e-posta, sana söyledikleri tarih geçtikten sonra: hâlâ ilgilendiğini söyle ve sonraki adımları kibarca sor.","fa":"دو ایمیلی را که بعد از مصاحبه لازم داری بنویس (در مجموع ۸۰ تا ۱۱۰ کلمه). ایمیل ۱، ظرف ۲۴ ساعت: تشکر کن، یک چیز واقعی از گفت‌وگو را یادآوری کن، بگو هنوز علاقه‌مندی. ایمیل ۲، بعد از گذشتن تاریخی که گفته بودند: بگو هنوز علاقه‌مندی و مؤدبانه درباره‌ی مراحل بعدی بپرس."},"model":"Dear Ms Arslan,\nThank you for meeting me today. I enjoyed hearing about your plan to move reports to a new system, and it made me even more interested in the role.\nKind regards,\nYour name\n\nDear Ms Arslan,\nYou mentioned that you hoped to decide by 10 May. I am still very interested in the position. Could you tell me if there is any news about the next steps? I look forward to hearing from you.\nKind regards,\nYour name","frame":"Dear ___,\nThank you for ___. I enjoyed hearing about ___, and it ___.\nKind regards,\n___\n\nDear ___,\nYou mentioned that ___. I am still very interested in ___. Could you tell me if ___? I look forward to ___.\nKind regards,\n___","words":[{"word":"Thank you for"},{"word":"next steps"},{"word":"look forward"}],"minWords":70,"minSentences":5,"rubric":["Task done: both emails, with one real detail in the first","Organised: thanks, detail, interest; then reason for writing, one question","Language: thank you for + -ing; statement order after \"Could you tell me if\"","Tone: short and warm; no pressure and no complaint about waiting"],"rubricI18n":{"tr":["Görev: iki e-posta da var, ilkinde gerçek bir ayrıntı","Düzen: teşekkür, ayrıntı, ilgi; sonra yazma nedeni, tek soru","Dil: thank you for + -ing; \"Could you tell me if\" sonrası düz cümle sırası","Üslup: kısa ve sıcak; baskı yok, beklemekten şikâyet yok"],"fa":["کامل بودن کار: هر دو ایمیل، با یک نکته‌ی واقعی در اولی","نظم: تشکر، جزئیات، علاقه؛ بعد دلیل نوشتن، یک سؤال","زبان: فعل با ing بعد از thank you for؛ ترتیب جمله‌ی خبری بعد از «Could you tell me if»","لحن: کوتاه و گرم؛ بدون فشار و بدون گله از انتظار"]}},"speaking":{"id":"int-cp-3","course":"interview","unit":"int-cp-3","topic":{"en":"Three surprise questions","tr":"Üç sürpriz soru","fa":"سه سؤال غافلگیرکننده"},"warmup":{"en":"You haven't prepared these. Take one breath, and use your phrase for time.","tr":"Bunlara hazırlanmadın. Bir nefes al ve zaman kazandıran ifadeni kullan.","fa":"برای این‌ها آماده نشده‌ای. یک نفس بکش و از عبارتت برای گرفتن وقت استفاده کن."},"questions":[{"en":"\"Why should we hire you and not someone with more experience?\"","tr":"\"Why should we hire you and not someone with more experience?\"","fa":"«Why should we hire you and not someone with more experience?»"},{"en":"\"What would you do if you disagreed with your manager?\"","tr":"\"What would you do if you disagreed with your manager?\"","fa":"«What would you do if you disagreed with your manager?»"},{"en":"\"Tell me about something you failed at.\"","tr":"\"Tell me about something you failed at.\"","fa":"«Tell me about something you failed at.»"}],"followups":[{"en":"Answer all three in 90 seconds, then 60, then 45. Honest, short, back to the job.","tr":"Üçünü de önce 90, sonra 60, sonra 45 saniyede cevapla. Dürüst ol, kısa tut, konuyu işe getir.","fa":"به هر سه اول در ۹۰، بعد در ۶۰ و بعد در ۴۵ ثانیه جواب بده. صادقانه و کوتاه جواب بده و حرف را به همین شغل برگردان."}],"expressions":[{"phrase":"That's a good question. Let me think for a moment.","meaning":{"en":"Gives you time, and sounds calm.","tr":"Sana zaman kazandırır ve sakin duyulur.","fa":"به تو وقت می‌دهد و آرام نشانت می‌دهد."}},{"phrase":"First I would...","meaning":{"en":"Opens your answer to \"What would you do if...?\"","tr":"\"What would you do if...?\" cevabını başlatır.","fa":"جوابت به «What would you do if...?» را شروع می‌کند."}},{"phrase":"What I learned was...","meaning":{"en":"Turns a failure into something useful.","tr":"Bir başarısızlığı işe yarar bir şeye çevirir.","fa":"یک شکست را به چیزی مفید تبدیل می‌کند."}}],"model":"That's a good question. Let me think for a moment. Do you mean my current manager? Okay. If I disagreed with my manager, first I would listen and make sure I understood the reason. Then I would explain my view in private, with facts. If the decision stayed the same, I would do the work well. In my last job I did that once, and we found a better plan together.","selfCheck":[{"en":"I used a phrase for time instead of staying silent.","tr":"Sessiz kalmak yerine zaman kazandıran bir ifade kullandım.","fa":"به‌جای سکوت، از عبارتی برای گرفتن وقت استفاده کردم."},{"en":"For \"What would you do?\" I said my first step.","tr":"\"What would you do?\" için ilk adımımı söyledim.","fa":"برای «What would you do?» قدم اولم را گفتم."},{"en":"I told the truth and blamed nobody.","tr":"Doğruyu söyledim ve kimseyi suçlamadım.","fa":"حقیقت را گفتم و کسی را مقصر ندانستم."},{"en":"I came back to this job at least once.","tr":"En az bir kez konuyu bu işe getirdim.","fa":"دست‌کم یک بار برگشتم سراغ همین شغل."}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
